/**
 * Single source of truth: packages/codingmon/assets/data/codingmon-50.json.
 * Browser mirrors are generated by scripts/assets/build-codingmon.mjs --write.
 */
import canonical from './data/codingmon-50.json' with { type: 'json' };

export const KATALOG_META = Object.freeze(canonical.metadata);
export const SPECIES_LIST = Object.freeze(canonical.species.map((species) => Object.freeze({
  ...species,
  stats: Object.freeze({ ...species.stats }),
  traits: Object.freeze([...(species.traits ?? [])]),
  abilityIds: Object.freeze([...(species.abilityIds ?? [])]),
  inheritedAbilityIds: Object.freeze([...(species.inheritedAbilityIds ?? [])]),
  children: Object.freeze([...(species.children ?? [])]),
  familyMeta: Object.freeze({ ...(species.familyMeta ?? {}) }),
  unlock: Object.freeze({ ...(species.unlock ?? {}) }),
})));
export const SPECIES_IDS = Object.freeze(SPECIES_LIST.map((species) => species.id));
export const SPECIES = Object.freeze(Object.fromEntries(SPECIES_LIST.map((species) => [
  species.id,
  Object.freeze({
    ...species.stats, id: species.id, name: species.name, label: species.name,
    family: species.family, hue: species.hue, role: species.role, description: species.description,
    traits: species.traits, rarity: species.rarity, ancestor: species.ancestor ?? null,
    lineageDepth: species.lineageDepth, familyMeta: species.familyMeta,
    abilityIds: species.abilityIds, inheritedAbilityIds: species.inheritedAbilityIds,
    children: species.children, unlock: species.unlock,
  }),
])));
/** Static ancestry depth is not a creature's dynamic breeding generation. */
export const LINEAGE = Object.freeze(Object.fromEntries(Object.entries(canonical.lineage).map(([id, entry]) => [
  id, Object.freeze({ ancestor: entry.ancestor ?? null, depth: entry.depth, inherits: Object.freeze([...(entry.inherits ?? [])]) }),
])));
export const ABILITIES = Object.freeze(canonical.abilities.map((ability) => Object.freeze({ ...ability })));
export const ELEMENTS = Object.freeze(Object.fromEntries(Object.entries(canonical.metadata.elements).map(([id, value]) => [
  id, Object.freeze({
    label: value.label, element: value.element, color: value.color, dark: value.dark, accent: value.accent,
    beats: value.matchup_beats, losesTo: value.loses_to,
  }),
])));
export const ELEMENT_CHART = Object.freeze(Object.fromEntries(Object.entries(canonical.elementChart).map(([attacker, matchups]) => [
  attacker, Object.freeze({ ...matchups }),
])));
export const BUFFS = Object.freeze(canonical.buffs.map((buff) => Object.freeze({
  id: buff.id, label: buff.label, factor: buff.factor,
  test: buff.trigger === 'inherited' ? 'inherited'
    : buff.trigger === 'hp < 25%' ? 'low-hp'
      : buff.trigger === 'hp >= 90%' ? 'full-hp' : null,
})));
export const LOOT_TABLE = Object.freeze(canonical.lootTable.map((entry) => Object.freeze({ ...entry })));
export const LOOT_TOTAL = LOOT_TABLE.reduce((sum, entry) => sum + entry.weight, 0);

export function validateCatalog(data = canonical) {
  const ids = data.species.map((species) => species.id);
  const idSet = new Set(ids);
  const abilityIds = data.abilities.map((ability) => ability.id);
  const abilitySet = new Set(abilityIds);
  if (ids.length !== 50 || idSet.size !== 50 || data.metadata.count?.total !== 50) throw new Error('Katalog muss genau 50 Spezies enthalten');
  if (abilityIds.length !== 101 || new Set(abilityIds).size !== 101 || data.metadata.count?.abilities !== 101) throw new Error('Katalog muss genau 101 Fähigkeiten enthalten');
  for (const species of data.species) {
    if (!/^[a-z][a-z0-9]*$/.test(species.id) || !species.name
      || !['spark', 'byte', 'feral'].includes(species.family)
      || !Number.isSafeInteger(species.hue) || species.hue < 0 || species.hue > 359
      || !['hp', 'atk', 'def', 'agi', 'int'].every((key) => Number.isSafeInteger(species.stats?.[key]) && species.stats[key] > 0)) {
      throw new Error('Ungültiger CodingMon-Speziesdatensatz: ' + species.id);
    }
    const line = data.lineage[species.id];
    if (!line || line.depth !== species.lineageDepth || line.ancestor !== (species.ancestor ?? null)) throw new Error('Linie/Tiefe widerspricht Speziesdaten für ' + species.id);
    if (line.ancestor !== null && !idSet.has(line.ancestor)) throw new Error('Fehlender Vorfahr für ' + species.id);
    for (const child of species.children ?? []) if (!idSet.has(child) || data.lineage[child]?.ancestor !== species.id) throw new Error('Fehlender/widersprüchlicher Nachkomme ' + species.id + ' -> ' + child);
    for (const id of [...(species.abilityIds ?? []), ...(species.inheritedAbilityIds ?? [])]) if (!abilitySet.has(id)) throw new Error('Fehlende Fähigkeit ' + id + ' für ' + species.id);
    for (const id of line.inherits ?? []) {
      const ability = data.abilities.find((item) => item.id === id);
      if (!ability || ability.species !== line.ancestor) throw new Error('Ungültige vererbte Fähigkeit ' + species.id + ' -> ' + id);
    }
    if (species.familyMeta?.matchup_beats !== data.metadata.elements[species.family]?.matchup_beats
      || species.familyMeta?.loses_to !== data.metadata.elements[species.family]?.loses_to) throw new Error('Elementmetadaten widersprechen dem Regelkreis für ' + species.id);
  }
  for (const [id, entry] of Object.entries(data.lineage)) {
    const seen = new Set([id]); let parent = entry.ancestor ?? null;
    while (parent !== null) {
      if (!data.lineage[parent] || seen.has(parent)) throw new Error('Zyklus/fehlende Linie: ' + id);
      seen.add(parent); parent = data.lineage[parent].ancestor ?? null;
    }
  }
  for (const ability of data.abilities) if (!['hp','atk','def','agi','int'].includes(ability.stat) || !['physisch','speziell'].includes(ability.kind)
    || !Number.isSafeInteger(ability.power) || ability.power < 1 || !Number.isSafeInteger(ability.minLevel) || ability.minLevel < 1
    || (ability.species !== null && !idSet.has(ability.species))) throw new Error('Ungültige Fähigkeit: ' + ability.id);
  if (Object.keys(data.elementChart).length !== 3 || Object.values(data.elementChart).some((row) => Object.keys(row).length !== 3)
    || data.lootTable.reduce((sum, item) => sum + item.weight, 0) !== 10000
    || data.buffs.some((buff) => !['inherited','hp < 25%','hp >= 90%'].includes(buff.trigger))) throw new Error('Unvollständige Regeltabellen');
  return Object.freeze({species:ids.length,abilities:abilityIds.length,lootWeight:data.lootTable.reduce((n,x)=>n+x.weight,0)});
}
export const CATALOG_VALIDATION = validateCatalog();
